// =============================================================
// EF Core 9 — Cosmos DB Breaking Change Fixes
// Apply these to your Cosmos DB project.
// =============================================================

using Microsoft.EntityFrameworkCore;

// -------------------------------------------------------------
// FIX 1: Discriminator property renamed from "Discriminator" to "$type".
//   Existing documents use "Discriminator". Preserve old name:
// -------------------------------------------------------------
// In your OnModelCreating:
//   modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

// -------------------------------------------------------------
// FIX 2: id property no longer contains the discriminator value.
//   Existing docs have "EntityType|KeyValue" format. Preserve it:
// -------------------------------------------------------------
// In your OnModelCreating:
//   modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);

// -------------------------------------------------------------
// FIX 3: Synchronous I/O no longer supported.
//   Replace all sync calls with async equivalents.
// -------------------------------------------------------------

class CosmosQueryExamples
{
    // BREAKS — sync calls now throw InvalidOperationException
    // void GetItems(CosmosDbContext db)
    // {
    //     var items = db.Products.ToList();
    //     db.SaveChanges();
    // }

    // FIX — use async equivalents
    async Task GetItemsAsync(CosmosDbContext db)
    {
        var items = await db.Products.ToListAsync();
        await db.SaveChangesAsync();
    }
}

// Example Cosmos DbContext with all three fixes applied
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // FIX 1: Keep old discriminator property name for existing documents
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // FIX 2: Keep old compound id format for existing documents
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
    }
}

class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
}

